package net.civeira.phylax.feature.observe.observedsource.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.observe.observedsource.domain.ObservedSource;
import net.civeira.phylax.feature.observe.observedsource.domain.valueobject.RateLimitVO;

class RateLimitValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of rate limit of observed source")
  void test_rate_limit_value_holder_assign_plain_value() {
    Object holder = new Object();
    RateLimitValueHolder<Object> value = new RateLimitValueHolder<>(holder);
    Assertions.assertSame(holder, value.rateLimit(1), "Setters must return the holder");
    Assertions.assertTrue(value.getRateLimitValue().isPresent(), "The plain value must be stored");
    Assertions.assertEquals(1, value.getRateLimit().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.rateLimitNull(), "Setters must return the holder");
    Assertions.assertTrue(value.getRateLimitValue().isPresent(),
        "A null value object must be stored");
    Assertions.assertFalse(value.getRateLimit().isPresent(), "A null value must not have content");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of rate limit of observed source")
  void test_rate_limit_value_holder_assign_value_object() {
    Object holder = new Object();
    RateLimitValueHolder<Object> value = new RateLimitValueHolder<>(holder);
    RateLimitVO vo = RateLimitVO.from(1);
    Assertions.assertFalse(value.getRateLimitValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.rateLimit(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getRateLimitValue().orElseThrow());
    Assertions.assertSame(holder, value.rateLimit(Optional.empty()));
    Assertions.assertFalse(value.getRateLimitValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.rateLimit(Optional.of(vo)));
    Assertions.assertSame(vo, value.getRateLimitValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of rate limit of observed source against the original")
  void test_rate_limit_value_holder_read() {
    Object holder = new Object();
    RateLimitValueHolder<Object> value = new RateLimitValueHolder<>(holder);
    RateLimitVO vo = RateLimitVO.from(1);
    RateLimitVO other = RateLimitVO.from(1);
    ObservedSource original = Mockito.mock(ObservedSource.class);
    Mockito.when(original.getRateLimitValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readRateLimit(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readRateLimit(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.rateLimit(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readRateLimit(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readRateLimit(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of rate limit of observed source")
  void test_rate_limit_value_holder_unset() {
    Object holder = new Object();
    RateLimitValueHolder<Object> value = new RateLimitValueHolder<>(holder);
    RateLimitVO vo = RateLimitVO.from(1);
    value.rateLimit(vo);
    Assertions.assertSame(holder, value.unsetRateLimitIfMatches("rateLimit_other"));
    Assertions.assertTrue(value.getRateLimitValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetRateLimitIfMatches("rateLimit"));
    Assertions.assertFalse(value.getRateLimitValue().isPresent(),
        "The field name must clear the value");
    value.rateLimit(vo);
    Assertions.assertSame(holder, value.unsetRateLimit());
    Assertions.assertFalse(value.getRateLimitValue().isPresent(), "Unset must clear the value");
  }
}
